import android.media.*; public class CodecProbe { public static void main(String[] args) { for(MediaCodecInfo i: new MediaCodecList(MediaCodecList.ALL_CODECS).getCodecInfos()) { if(i.isEncoder())continue; for(String t:i.getSupportedTypes())if(t.equals("video/avc")) {System.out.println(i.getName()+" software="+i.isSoftwareOnly()+" hardware="+i.isHardwareAccelerated()+" supports1024x768="+i.getCapabilitiesForType(t).getVideoCapabilities().isSizeSupported(1024,768));} } } }
